def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import time, timedelta

    try:
        if nanoseconds is None:
            return time(0, 0, 0, tzinfo=tz) if tz is not None else time(0, 0, 0)

        total_seconds, nanosecs = divmod(nanoseconds, 1_000_000_000)
        days, seconds = divmod(total_seconds, 86400)
        hours, seconds = divmod(seconds, 3600)
        minutes, seconds = divmod(seconds, 60)

        if tz is not None:
            return time(hours, minutes, seconds, nanosecs, tzinfo=tz)
        else:
            return time(hours, minutes, seconds, nanosecs)
    except (ValueError, TypeError, OverflowError):
        # Invalid input occurs, typically from invalid nanoseconds or tz
        return None

