def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None

    try:
        # If it's already a string, return it as is.
        if isinstance(value, str):
            return value

        # Convert to datetime.time if needed.
        if not hasattr(value, 'hour'):
            raise ValueError("Invalid time object: missing time attributes")

        # Return as HH:MM:SS format string.
        seconds = value.second
        micro = value.microsecond
        if micro:
            # Include microseconds for precision, but usually omit seconds if not needed.
            return value.isoformat()
        else:
            return f"{value.hour:02d}:{value.minute:02d}:{seconds:02d}"

    except Exception:
        raise

