def round_half_to_even(n):
    import math
    if n < 0:
        sign = -1
        abs_n = abs(n)
    else:
        sign = 1
        abs_n = n
    floor_val = math.floor(abs_n)
    fractional = abs_n - floor_val
    if fractional < 0.5:
        rounded = floor_val
    elif fractional > 0.5:
        rounded = floor_val + 1
    else:
        # fractional == 0.5
        rounded = floor_val if floor_val % 2 == 0 else floor_val + 1
    return sign * rounded

