        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :return The exception readable string
        :rtype str
        """
        import traceback
        import os

        if not isinstance(e, Exception):
            raise TypeError("Expected an Exception instance, got " + str(type(e)))

        # Get the traceback for the exception
        tb = e.__traceback__

        # Format the traceback
        if tb is None:
            tb_str = "Traceback (most recent call last):\n  No traceback available\n"
        else:
            # Convert traceback to list of frames
            tb_frames = []
            current_tb = tb
            while current_tb is not None:
                frame = current_tb.tb_frame
                filename = frame.f_code.co_filename
                name = frame.f_code.co_name
                filename = os.path.basename(filename)
                tb_str_relevant = os.path.basename(filename) + ":" + str(current_tb.tb_lineno) + " in " + name
                tb_frames.append(tb_str_relevant)
                current_tb = current_tb.tb_next

            # Apply max_level slicing
            if len(tb_frames) > max_level:
                tb_frames = tb_frames[-max_level:]

            tb_str = "Traceback (most recent call last):\n"
            for frame_info in tb_frames:
                # Simplify path level
                parts = frame_info.split("/")
                if len(parts) > max_path_level:
                    frame_info = "..." + "/" + "/".join(parts[-max_path_level:])
                tb_str += "  " + frame_info + "\n"

        # Add the exception message
        try:
            if e.args:
                # Handle multiple args properly
                msg = str(e)
            else:
                msg = type(e).__name__

            if tb_str and not tb_str.endswith("\n"):
                tb_str += "\n"
            if tb_str and tb_str != "Traceback (most recent call last):\n  No traceback available\n":
                 result = tb_str + msg + "\n"
            else:
                if tb_str == "Traceback (most recent call last):\n  No traceback available\n":
                     result = tb_str + msg
                elif not tb_str:
                    result = msg
                else:
                    result = tb_str + msg
        except Exception as inner_ex:
            result = f"Exception formatting error: {type(e).__name__}: {inner_ex}"

        return result.strip()

