def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if bins is None or edges is None:
        return 0.0
    if len(bins) == 0:
        return 0.0
    if len(edges) < 2:
        return 0.0
    if len(edges) != len(bins) + 1:
        raise ValueError("Inconsistent number of bins and edges")
    result = 0.0
    for i, (val, left, right) in enumerate(zip(bins, edges[:-1], edges[1:])):
        width = right - left
        if width < 0:
            width = -width
        result += val * width
    return result

