def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        try:
            indices = self._get_indices(coord)
        except Exception:
            return

        # If the function is not provided, assume the histogram is 1D
        if self._function is not None:
            function = self._function
            transformed = function(coord)
        else:
            transformed = coord

        # For 1D histogram with scalar coord
        if self._ndim == 1:
            # histograms can be either 1D or multi-D depending on the edges array shape
            # we can use the first set of edges if we assume 1D
            edges = self._edges[0] if len(self._edges) > 0 else None
            if edges is not None:
                # find the index using searchsorted
                # use bisect_right for the upper edges - bin is [edges[i], edges[i+1])
                try:
                    idx = int(np.searchsorted(edges, transformed, side='right')) - 1
                except Exception:
                    return

                # check if idx is within the valid range
