            except (TypeError, AttributeError):
                # This should not happen for str/bytes, but just in case
                errors.append({str(key): 'expected string or bytes-like object'})

        # Then, check the value
        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
        else:
            # For string or bytes values, check the pattern
            try:
                if not value_pattern.match(value if isinstance(value, str) else value.decode('utf-8')):
