def _explore_zipfile(zip_path):
    import zipfile
    import os
    import xml.etree.ElementTree as ET

    data = {}

    try:
        if not os.path.exists(zip_path):
            return data
        if not os.path.isfile(zip_path):
            return data
        if not zip_path.lower().endswith('.zip'):
            return data

        with zipfile.ZipFile(zip_path, 'r') as zip_file:
            for file_name in zip_file.namelist():
                # Skip directories
                if file_name.endswith('/'):
                    continue

                # Only process XML files
                if not file_name.lower().endswith('.xml'):
                    continue

                try:
                    with zip_file.open(file_name) as xml_file:
                        content = xml_file.read()
                        try:
                            root = ET.fromstring(content)
                        except ET.ParseError:
                            # If XML parsing fails, skip this file
                            continue

                        tree = ET.ElementTree(root)
                        root = tree.getroot()

                        # Try to get basename from attrib first, then fallback to filename
                        basename = root.attrib.get('name') or root.attrib.get('basename')
                        if not basename:
                            # Use the base name of the file in the zip (without extension)
                            basename = os.path.splitext(os.path.basename(file_name))[0]

                        # If basename is not a string or empty, skip
                        if not isinstance(basename, str) or not basename:
                            continue

                        # Store root element in the data dict
                        data[basename] = root

                except (OSError, zipfile.BadZipFile, ET.ParseError):
                    # Skip files that cause errors
                    continue

    except (OSError, zipfile.BadZipFile):
        # If the zip file itself is invalid or inaccessible, return empty dict
        pass

    return data

