def _extract_number_and_suppl_from_issue_element(issue):
    """
    Extract from the content of <issue>xxxx</issue>, the values number and suppl.
    Possible values
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    if not issue:
        return {'number': None, 'suppl': None}

    import re

    issue_stripped = str(issue).strip()
    if not issue_stripped:
        return {'number': None, 'suppl': None}

    # Normalize: convert to lowercase for easier pattern matching
    s = issue_stripped.lower()

    # Patterns for "suppl" indicator
    # suppl, supp, spe, supl, s
    suppl_indicators = r'(?:suppl\.?|supp\.?|spe\.?|supl\.?|s)'

    # Pattern to match number and optional supplementary number
    # The structure is: [number] [suppl_indicator] [suppl_number]
    # Number can be a range like 2-5
    # suppl_number can be a simple number or a range like 1-2

    # Let's try to match various patterns

    # Pattern 1: pure number (no suppl)
    m = re.fullmatch(r'(\d+(?:-\d+)?)', s)
    if m:
        return {'number': m.group(1), 'suppl': None}

    # Pattern 2: number followed by suppl indicator, optionally with suppl number
    # e.g., "5 suppl", "5 suppl 1", "5 suppl. 1", "5 spe", "5 spe 1", "5 spe pr", "5 spe2", "5 spe.2"
    m = re.fullmatch(r'(\d+(?:-\d+)?)\s*(' + suppl_indicators + r')\s*(\d+(?:-\d+)?)?', s)
    if m:
        number = m.group(1)
        suppl_num = m.group(3)
        return {'number': number, 'suppl': int(suppl_num) if suppl_num else None}

    # Pattern 3: suppl indicator followed by number (no leading number)
    # e.g., "Spe", "Supl. 1", "Suppl", "Suppl 12", "s2", "spe 1", "spe pr", "spe2", "spe.2"
    m = re.fullmatch(r'(' + suppl_indicators + r')\s*(\d+(?:-\d+)?)?', s)
    if m:
        suppl_num = m.group(2)
        return {'number': None, 'suppl': int(suppl_num) if suppl_num else None}

    # Pattern 4: number range with suppl
    # e.g., "2-5 suppl 1"
    m = re.fullmatch(r'(\d+-\d+)\s*(' + suppl_indicators + r')\s*(\d+(?:-\d+)?)?', s)
    if m:
        number = m.group(1)
        suppl_num = m.group(3)
        return {'number': number, 'suppl': int(suppl_num) if suppl_num else None}

    # Specific patterns with special notation
    # "5 (suppl)" or similar
    m = re.fullmatch(r'(\d+(?:-\d+)?)\s*\((?:suppl|supp|spe|supl)\)', s)
    if m:
        return {'number': m.group(1), 'suppl': None}

    # "spe pr" or "spepr"
    if s in ('spe pr', 'spepr', 'spe.pr', 'spe.pr'):
        return {'number': None, 'suppl': None}

    # Fallback: try to extract any number
    numbers = re.findall(r'\d+(?:-\d+)?', s)
    if numbers:
        number = numbers[0]
        # Check if there's a suppl indicator
        has_suppl = bool(re.search(suppl_indicators, s))
        if len(numbers) > 1:
            suppl_num = numbers[1]
            return {'number': number, 'suppl': int(re.match(r'\d+', suppl_num).group()) if has_suppl else int(number.split('-')[-1]) if '-' in number else None}
        else:
            return {'number': number, 'suppl': None}

    # No numbers found
    return {'number': None, 'suppl': None}

