    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata
        try:
            # Try to get the version of the current package
            # Since we don't know the package name, try common approaches
            # First, try to infer from the calling module
            import sys, inspect
            try:
                # Try to get the package name from the caller's stack
                caller_frame = inspect.stack()[1]
                caller_module = inspect.getmodule(caller_frame.frame)
                if caller_module and caller_module.__name__ != '__main__':
                    pkg_name = caller_module.__name__.split('.')[0]
                    return importlib.metadata.version(pkg_name)
            except Exception:
