def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
  # Combine commands and args into a list for subprocess
  # If commands is a string, split it by spaces, otherwise treat as list
  if isinstance(commands, str):
    cmd_list = commands.split()
  else:
    cmd_list = list(commands)

  if args is not None:
    if isinstance(args, str):
      cmd_list.extend(args.split())
    else:
      cmd_list.extend(args)

  import subprocess

  try:
    if verbose:
      print(f"Running: {' '.join(cmd_list)}")
      if cwd:
        print(f"  cwd: {cwd}")

      result = subprocess.run(
          cmd_list,
          cwd=cwd,
          env=env,
          stdout=subprocess.PIPE,
          stderr=subprocess.PIPE if not hide_stderr else None,
          text=True
      )

      if verbose:
        if result.stdout:
          print(result.stdout, end='')
        if not hide_stderr and result.stderr:
          print(result.stderr, end='', file=sys.stderr)

        return result.returncode
    else:
      # Non-verbose: don't capture stdout/stderr to avoid blocking (except when hide_stderr)
      stdout = subprocess.PIPE if hide_stderr else None
      stderr = subprocess.PIPE if hide_stderr else None

      result = subprocess.run(
          cmd_list,
          cwd=cwd,
          env=env,
          stdout=stdout,
          stderr=stderr,
      )

      return result.returncode

  except Exception as e:
    if verbose:
      print(f"Error running command: {e}")
    return -1

