def find_path_type(path):
    import os
    import re

    if not path:
        return 'empty path'

    if not os.path.exists(path):
        return 'no such path'

    try:
        if os.path.isfile(path):
            return 'file'

        if not os.path.isdir(path):
            return 'not a file or directory'

        # Look for Namaste files (0=*) in the directory
        namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]

        if not namaste_files:
            return 'not a root or object (no Namaste files)'

        # Check for root indicators
        for namaste_file in namaste_files:
            if namaste_file.startswith('0=root'):
                return 'root'

        # Check for object indicators
        for namaste_file in namaste_files:
            if re.match(r'^0=object', namaste_file):
                return 'object'

        # If we have Namaste files but they don't match known patterns
        return 'unknown OCFL path type'

    except Exception as e:
        return f'error: {str(e)}'

