    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple")

    # Handle edge case where bug_ids is empty
    if len(bug_ids) == 0:
        return params

    # Create a copy of params to avoid modifying the original
    amended_params = dict(params)

    # If bug_ids only has one element, use its string representation
    if len(bug_ids) == 1:
        amended_params['ids'] = str(bug_ids[0])
    else:
        # Join bug_ids with commas, as is typical for Bugzilla API
        amended_params['ids'] = ','.join(str(bid) for bid in bug_ids)

    return amended_params

