def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def deep_merge_mappings(mapping_nodes_list):
        """
        Deep merge a list of MappingNode objects into a single MappingNode.
        """
        try:
            from ruamel.yaml.nodes import MappingNode, ScalarNode
        except ImportError:
            raise ImportError("ruamel.yaml is required for deep merge")

        if not mapping_nodes_list:
            return None

        result_value = []
        seen_keys = set()

        for mapping_node in mapping_nodes_list:
            for sub_key, sub_value in mapping_node.value:
                # Create a hashable key representation
                if hasattr(sub_key, 'value') and hasattr(sub_key, 'tag'):
                    sub_key_rep = (sub_key.tag, str(sub_key.value))
                else:
                    sub_key_rep = id(sub_key)

                if sub_key_rep not in seen_keys:
                    # Add the key-value pair
                    result_value.append((sub_key, sub_value))
                    seen_keys.add(sub_key_rep)
                else:
                    # Find and replace the existing key-value pair
                    for i, (existing_key, existing_value) in enumerate(result_value):
                        if hasattr(existing_key, 'value') and hasattr(existing_key, 'tag'):
                            existing_key_rep = (existing_key.tag, str(existing_key.value))
                        else:
                            existing_key_rep = id(existing_key)

                        if existing_key_rep == sub_key_rep:
                            # Check if both values are mapping nodes for deep merge
                            if isinstance(existing_value, MappingNode) and isinstance(sub_value, MappingNode):
                                # Replace with deep merged mapping
                                merged_sub = deep_merge_mappings([existing_value, sub_value])
                                result_value[i] = (sub_key, merged_sub)
                            else:
                                # Last value wins
                                result_value[i] = (sub_key, sub_value)
                            break

        return MappingNode(tag='tag:yaml.org,2002:map', value=result_value)
    # Import necessary modules inside the function to avoid top-level imports
    try:
        from ruamel.yaml.nodes import MappingNode, ScalarNode
    except ImportError:
        # If ruamel.yaml is not available, we need to handle it gracefully
        # But in a real borgmatic context, it should be available.
        # For now, we'll just let it fail naturally if someone tries to use it without ruamel.yaml
        pass

    if not nodes:
        return nodes

    # Use a dict to preserve order (Python 3.7+ dicts are ordered)
    # Key: tuple representing the key node (tag, value) for ScalarNode
    # Value: list of value nodes to merge
    merged = {}
    order = []

    for key, value in nodes:
        # Create a hashable representation of the key
        # For ScalarNode, we can use (tag, value)
        if hasattr(key, 'value') and hasattr(key, 'tag'):
            key_rep = (key.tag, str(key.value))
        else:
            # Fallback for other node types
            key_rep = id(key)

        if key_rep not in merged:
            merged[key_rep] = {'key': key, 'values': []}
            order.append(key_rep)

        merged[key_rep]['values'].append(value)

    result = []
    for key_rep in order:
        entry = merged[key_rep]
        key = entry['key']
        values = entry['values']

        # Check the type of values to determine how to merge
        if not values:
            continue

        # Check if all values are MappingNode
        all_mapping = all(isinstance(v, MappingNode) for v in values)

        if all_mapping:
            # Deep merge all mapping nodes
            merged_value = deep_merge_mappings(values)
            result.append((key, merged_value))
        else:
            # For non-mapping nodes or mixed types, the last one wins
            # But we need to handle the case where some are mapping and some aren't
            # According to the docstring: "If there are colliding keys with non-MappingNode values (e.g., integers or strings), the last of the values wins."
            # This implies that if ALL are mapping nodes, we deep merge. Otherwise, the last wins (which could be a mapping node or not)
            result.append((key, values[-1]))

    return result

