    import hashlib
    h = hashlib.new(sha)
    h.update(path_bytes)
    computed_digest = h.hexdigest()
    expected_digest = hash_bytes.decode('utf-8') if isinstance(hash_bytes, bytes) else hash_bytes
    if computed_digest != expected_digest:
        raise ValueError(f"Hash mismatch: computed {computed_digest}, expected {expected_digest}")
    return f"borgmatic_complete {path.decode('utf-8') if isinstance(path, bytes) else path}"

