def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict")

    parsed = {}
    remaining = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        if parser is None:
            continue
        try:
            # We want to see if this subparser can parse the current remaining arguments
            # Use parse_known_args to get parsed namespace and remaining args
            namespace, args = parser.parse_known_args(args=remaining, prefix_chars='-', prog=str(subparser_name))
            # Only consider this subparser if it actually parsed at least one known argument
            # We can check if namespace is not empty or if args differ from remaining
            if namespace:
                parsed[subparser_name] = namespace
                remaining = list(args)
        except SystemExit:
            # argparse may call sys.exit on error
            continue
        except Exception:
            # If any error occurs, skip this subparser
            continue

    return (parsed, remaining)

