def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        return "" if number == 0 else ""

    base = len(alphabet)

    if number == 0:
        result = alphabet[0]
        if padding is not None and padding > 1:
            result = alphabet[0] * (padding - 1) + result
        return result

    is_negative = number < 0
    if is_negative:
        number = -number

    chars = []
    while number > 0:
        remainder = number % base
        if remainder >= len(alphabet):
            remainder = len(alphabet) - 1
        chars.append(alphabet[remainder])
        number = number // base

    result = ''.join(reversed(chars))

    if is_negative:
        result = '-' + result

    if padding is not None:
        if len(result) < padding:
            result = '0' * (padding - len(result)) + result if not is_negative else '-' + '0' * (padding - len(result) - 1) + result

    return result

