def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    def convert_wildcard_to_regex(key):
        # Convert wildcard patterns to regex
        # Escape all special regex characters except * and ?, then replace them
        regex = ''
        i = 0
        while i < len(key):
            if key[i] == '*':
                regex += '.*'
            elif key[i] == '?':
                regex += '.'
            else:
                regex += re.escape(key[i])
            i += 1
        return regex

    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")

    result = {}
    for key, value in item.items():
        if isinstance(key, str):
            new_key = '^' + convert_wildcard_to_regex(key) + '$'
        else:
            new_key = key
        result[new_key] = value
    return result

