    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    import datetime
    if frequency is None:
        return None
    frequency = frequency.strip().lower()
    if frequency == 'always':
        return None

    try:
        if ' ' not in frequency:
            raise ValueError(f"Invalid frequency format: '{frequency}'")

        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError(f"Invalid frequency format: '{frequency}'")

        num_str, unit = parts

        # Try to parse the number (allow integers and floats)
        try:
            num = int(num_str)
        except ValueError:
            try:
                num = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number in frequency: '{num_str}'")

        # Map units to timedelta keyword arguments
        unit = unit.strip()
        timed_kwargs = {}

        # Handle singular and plural forms
        if unit in ['second', 'seconds', 's', 'sec', 'secs', 'sec.', 'secs.']:
            timed_kwargs['seconds'] = num
        elif unit in ['minute', 'minutes', 'min', 'mins', 'min.', 'mins.']:
            timed_kwargs['minutes'] = num
        elif unit in ['hour', 'hours', 'hr', 'hrs', 'hr.', 'hrs.']:
            timed_kwargs['hours'] = num
        elif unit in ['day', 'days', 'd', 'days.']:
            timed_kwargs['days'] = num
        elif unit in ['week', 'weeks', 'w', 'wks', 'wk', 'weeks.', 'wks.', 'wk.']:
            timed_kwargs['weeks'] = num
        elif unit in ['month', 'months', 'mo', 'mos', 'mo.', 'mos.']:
            # months are not directly supported by timedelta, convert to days (approx 30 days)
            timed_kwargs['days'] = num * 30
        elif unit in ['year', 'years', 'y', 'yr', 'yrs', 'year.', 'years.', 'yr.', 'yrs.']:
            # years are not directly supported, convert to days (approx 365 days)
            timed_kwargs['days'] = num * 365
        else:
            raise ValueError(f"Unknown time unit: '{unit}'")

        return datetime.timedelta(**timed_kwargs)

    except ValueError:
        raise
    except Exception as e:
