        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    # Strip whitespace
    frequency = frequency.strip()

    # Handle case where frequency is empty or invalid
    if not frequency:
        raise ValueError("Frequency string is empty or None")

    # Check if it contains a space separating number and unit
    if ' ' in frequency:
        parts = frequency.split(' ', 1)
        if len(parts) != 2:
            raise ValueError("Invalid frequency format: {}" .format(frequency))
        number_str, unit_str = parts
    else:
        # No space, try to parse the whole string
        # This might be a number with a unit without space, e.g. "3days"
        # But the example shows "3 weeks", so let's assume proper format with space
        # For robustness, we can try to extract number and unit
        import re
        match = re.match(r'^(\d+\.?\d*?)([a-zA-Z]+)$', frequency)
        if match:
            number_str = match.group(1)
            unit_str = match.group(2)
        else:
