def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    if not host:
        return False
    try:
        # Check if the host is localhost or 127.0.0.1 or ::1
        if host == "localhost" or host == "127.0.0.1" or host == "::1":
            return True

        # Try to resolve the hostname
        infos = socket.getaddrinfo(host, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for info in infos:
            family, socktype, proto, canonname, sockaddr = info
            if sockaddr[0] == "127.0.0.1" or sockaddr[0] == "::1":
                return True
        return False
    except socket.error:
        return False

