def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    from urllib.parse import urlparse
    if not image_href or not isinstance(image_href, str):
        raise ValueError("image_href must be a non-empty string")

    # Try to parse with urlparse
    try:
        parsed = urlparse(image_href)
    except Exception:
        raise ValueError(f"Invalid image href: '{image_href}'")

    # Check if it's a relative path or has a valid scheme
    if not parsed.scheme:
        # Could be a local path or relative URL
        netloc = ""
        use_ssl = False
        # Extract image_id from path
        path = parsed.path
        if path:
            # Take the last part of the path as image_id
            image_id = path.split('/')[-1] if path else ""
            # Strip query and fragment if any
            if image_id and '_fragment' in image_id:
                image_id = image_id.split('_fragment')[0]
        else:
            image_id = ""
    elif parsed.scheme in ('http', 'https'):
        netloc = parsed.netloc
        use_ssl = (parsed.scheme == 'https')
        # Extract image_id from path
        path = parsed.path
        if path:
            image_id = path.split('/')[-1] if path else ""
            # Strip query and fragment if any
            if image_id and '_fragment' in image_id:
                image_id = image_id.split('_fragment')[0]
        else:
            # No path, use netloc or empty?
            image_id = ""
    else:
        raise ValueError(f"Unsupported scheme in image_href: '{image_href}'")

    # Validate that we got an image_id
    if not image_id:
        # If no image_id, maybe the whole thing is the id?
        # Try to extract from the tail of the href
        tail = image_href.split('/')[-1]
        if tail and '?' not in tail and '#' not in tail:
            image_id = tail
        else:
            raise ValueError(f"Could not extract image_id from image_href: '{image_href}'")

    return (image_id, netloc, use_ssl)

