def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    # Find all parents and children based on the property
    # We want to find nodes that are parents in the hierarchy
    for parent, _, _ in graph.triples((None, prop, None)):
        roots.add(parent)

    # Find all children
    for _, _, child in graph.triples((None, prop, None)):
        roots.discard(child)

    return roots

