    try:
        # Check if shape is a valid tuple of non-negative integers
        if not isinstance(shape, tuple):
            shape = tuple(shape)  # Try to convert list, int, etc. to tuple
        for dim in shape:
            if not isinstance(dim, (int, np.integer)) or dim < 0:
                raise ValueError("Shape must be a tuple of non-negative integers")
