def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        return ""

    # Add target="_blank" and rel="noopener" to existing <a> and <img> tags
    def add_attrs(match):
        tag = match.group(0)
        if 'target=' in tag:
            # If target already exists, ensure rel="noopener" too
            if 'rel=' not in tag:
                return tag.replace('>', ' rel="noopener">', 1)
            return tag
        if 'rel=' in tag:
            return tag.replace('>', ' target="_blank">', 1)
        return tag.replace('>', ' target="_blank" rel="noopener">', 1)

    # Add attributes to <a> and <img> tags
    text = re.sub(r'<(a|img)\b[^>]*>', add_attrs, text, flags=re.IGNORECASE)

    # Linkify plain-text URLs (avoiding URLs already inside tags)
    url_pattern = r'(?<!href=")\b(https?://[^\s<]+)'
    text = re.sub(url_pattern, r'<a href="\1" target="_blank" rel="noopener">\1</a>', text)

    return text

