def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.dom import minidom

    if not document or not document.strip():
        return {}

    document_stripped = document.strip()

    # Try JSON first
    if document_stripped.startswith('{'):
        try:
            data = json.loads(document_stripped)
            if isinstance(data, dict):
                return data
        except (json.JSONDecodeError, ValueError):
            pass

    # Try XML (XRD format)
    if document_stripped.startswith('<'):
        try:
            dom = minidom.parseString(document_stripped)
            result = {}

            # Parse liens
            for lien in dom.getElementsByTagName("link"):
                rel = lien.getAttribute("rel") or lien.getAttribute("href")
                if rel:
                    if rel not in result:
                        result[rel] = []
                    href = lien.getAttribute("href")
                    if href:
                        result[rel].append(href)
                    # Handle alternate types
                    types = lien.getAttribute("type")
                    if types:
                        if rel not in result:
                            result[rel] = []
                        result['types'] = types

            # Also process subject
            subject_elements = dom.getElementsByTagName("subject")
            if subject_elements and len(subject_elements) > 0:
                subject_text = subject_elements[0].firstChild
                if subject_text:
                    result['subject'] = subject_text.nodeType == subject_text.TEXT_NODE and subject_text.data.strip() or ''

            return result
        except Exception:
            pass

    # If both failed, return empty dict
    return {}

