def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    import xml.etree.ElementTree as ET

    from typing import Dict
    result = {}
    document = document.strip()

    # Check if it's JSON
    if document.startswith('{'):
        try:
            data = json.loads(document)
        except json.JSONDecodeError:
            return {}

        subject = data.get('subject', '')
        links = data.get('links', [])

        result['subject'] = subject
        result['links'] = {}

        for link in links:
            relation = link.get('rel', '')
            href = link.get('href', '')
            if relation:
                result['links'][relation] = href

        return result

    # Check if it's XRD
    elif document.startswith('<') or document.startswith('<?xml'):
        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            return {}

        # XRD uses namespaces
        ns = {
            'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0',
            'rel': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'
        }

        # Try to find subject
        subject_elem = root.find('.//xrd:Subject', ns)
        if subject_elem is not None:
            result['subject'] = subject_elem.text or ''

        result['links'] = {}

        # Find all alias elements
        for alias_elem in root.findall('.//xrd:Alias', ns):
            alias_elem = alias_elem if alias_elem is not None else root.find('.//Alias')

        # Actually XRD format:
        # <XRD>
        #   <Subject>...</Subject>
        #   <Alias>...</Alias>
        #   <Link rel="..." href="..."/>
        # </XRD>

        result['links'] = {}

        for link_elem in root.findall('.//xrd:Link', ns):
            if link_elem is None:
                link_elem = root.find('.//Link')

        # Flavor without namespace
        for link_elem in root.iter():
            if link_elem.tag.endswith('}Link') or link_elem.tag == 'Link':
                rel = link_elem.get('rel', '')
                href = link_elem.get('href', '')
                if rel:
                    result['links'][rel] = href

        # Also get subject
        for elem in root.iter():
            if elem.tag.endswith('}Subject') or elem.tag == 'Subject':
                result['subject'] = elem.text or ''
                break

        return result

    return result

