def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    from typing import Optional

    import urllib.request

    import socket
    if not handle or not isinstance(handle, str):
        return None

    # Parse the handle to extract username and domain
    handle = handle.strip()

    # Handle might be in format user@domain or just user or domain
    if '@' in handle:
        username, domain = handle.split('@', 1)
    else:
        # Try to determine if it's username or domain
        # RFC 3986 and handle format suggests it might be user@domain
        # If no @, assume it's just a domain or we need to try default domain
        # For webfinger, we usually need account in format acct:user@domain
        username = handle
        domain = None

    # Build the webfinger URL
    # RFC 7033: .well-known/webfinger?resource=acct:username@domain
    if domain:
        account = f"acct:{username}@{domain}"
        base_url = f"https://{domain}/.well-known/webfinger"
    else:
        # If no domain, we can't form a proper acct URI, return None
        return None

    resource = urllib.parse.quote(account)
    url = f"{base_url}?resource={resource}"

    try:
        # Set socket timeout
        socket.setdefaulttimeout(5)
    except Exception:
        pass

    try:
        request = urllib.request.Request(
            url,
            headers={
                'User-Agent': 'Mozilla/5.0 (compatible; webfinger-client/1.0)',
                'Accept': 'application/json, application/jrd+json, application/ld+json'
            }
        )
        response = urllib.request.urlopen(request)
        if response.status == 200:
            content = response.read()
            # Try to decode as UTF-8
            try:
                return content.decode('utf-8')
            except UnicodeDecodeError:
                # Try latin-1 as fallback
                return content.decode('latin-1')
        else:
            return None
    except Exception:
        return None

