    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("First argument must be a dictionary")

    # If no keys are provided, we can't do anything
    if key is None:
        raise ValueError("First key cannot be None")

    # Start with the first key
    current = dic
    current[key] = {} if keys else val

    # Traverse the remaining keys
    for k in keys:
        if k is None:
            raise ValueError("Key cannot be None")
        # If the current value is not a dict, we need to replace it with a new dict
        if not isinstance(current, dict):
            current = {}
        elif current.get(k) is None or not isinstance(current.get(k), dict):
            current[k] = {}
        else:
            current = current[k]

    return dic

