def list_of_file_names(settings_dirs, spec_option):
    # Check if parameters are valid
    if not isinstance(settings_dirs, (list, tuple)) or not all(isinstance(d, str) for d in settings_dirs):
        raise TypeError("settings_dirs must be a list or tuple of strings")

    if spec_option is None:
        spec_option = ""
    elif not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string or None")

    # Prepare the filename list
    file_names = []
    for settings_dir in settings_dirs:
        # Skip empty directories
        if not settings_dir:
            continue
        base_name = spec_option.strip() if spec_option else ""
        if base_name:
            file_name = f"{base_name}.ini"
        else:
            # If no spec_option, use a default name
            file_name = "default.ini"
        file_names.append(f"{settings_dir.rstrip('/\\\\')}/{file_name}")

    return file_names

