                                spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Initialize with default values
        complex_type = {
            'subcommand': subcommand,
            'type_name': type_name,
            'option_name': option_name,
            'actions': [],
            'options': {},
        }

        # Process the spec_option if provided
        if spec_option:
            # If it's a dict, merge the specifications
            if isinstance(spec_option, dict):
                for key, value in spec_option.items():
                    complex_type[key] = value
            else:
                # If it's not a dict, treat it as a default value or simple spec
                complex_type['spec'] = spec_option
        else:
            # Default action if not provided
            complex_type['actions'] = ['required']

        # Ensure type_name is a string
        if not isinstance(complex_type['type_name'], str):
            complex_type['type_name'] = str(complex_type['type_name'])

        # Ensure option_name is a string
        if not isinstance(complex_type['option_name'], str):
            complex_type['option_name'] = str(complex_type['option_name'])

        return complex_type

    except Exception as e:
        # In case of any unexpected error, return a basic error structure
        return {
